"""v3.1: the image-based creative path, end to end, on photographic-style raster assets (procedural, NOT generated by a model):
a backdrop plate, a transparent-background cut-out layer and a detail plate -> camera push, parallax between the layers, an image-to-image
nested-scale transition, a recomposed 9:16 Short from the same scene data, expressive voice fields, media QA + motion QA on the delivered frames.
The assets are synthetic because the build sandbox cannot download Higgsfield results (see docs/STATUS.md); the engine path is the same for any PNG/JPEG."""
import json, pathlib, shutil
import numpy as np
import pytest
from conftest import ROOT, checks, ffprobe, make_project, py, run

W_, H_ = 1920, 1080


def _make_assets(A):
    from PIL import Image, ImageFilter
    rng = np.random.default_rng(7)
    y, x = np.mgrid[0:H_, 0:W_].astype(float)
    sky = np.stack([40 + 120 * (y / H_), 50 + 70 * (y / H_), 110 + 20 * (y / H_)], -1)
    sun = np.exp(-(((x - 1450) ** 2 + (y - 330) ** 2) / (2 * 38 ** 2)))[..., None] * np.array([255, 230, 160])
    ridge = (y > 640 + 60 * np.sin(x / 210.0) + 25 * np.sin(x / 63.0))[..., None] * np.array([-70.0, -60.0, -40.0])
    img = np.clip(sky + sun + ridge + 0, 0, 255).astype("uint8")
    Image.fromarray(img).filter(ImageFilter.GaussianBlur(0.8)).save(A / "plate.png")
    # transparent cut-out: a dark green blob with a soft alpha edge, fully transparent corners
    n = 800
    yy, xx = np.mgrid[0:n, 0:n].astype(float)
    r = np.sqrt(((xx - n / 2) / (n * 0.42)) ** 2 + ((yy - n / 2) / (n * 0.34)) ** 2)
    alpha = np.clip((1.0 - r) / 0.08, 0, 1)
    rgb = np.stack([np.full((n, n), 20.0), 90 + 40 * np.sin(xx / 17.0), np.full((n, n), 35.0)], -1)
    Image.fromarray(np.dstack([rgb, alpha * 255]).astype("uint8"), "RGBA").save(A / "cutout.png")
    # detail plate: warm fine texture
    yy, xx = np.mgrid[0:900, 0:1600].astype(float)
    det = np.stack([105 + 30 * np.sin(xx / 9.0 + yy / 40.0), 80 + 25 * np.sin(xx / 13.0), 70 + 20 * np.sin(yy / 7.0)], -1)
    Image.fromarray(np.clip(det + rng.normal(0, 4, det.shape), 0, 255).astype("uint8")).save(A / "detail.png")
    return {"plate": (W_, H_), "cutout": (n, n), "detail": (1600, 900)}


NARR = [
    "Look at the light on this ridge at dusk, and how it falls on everything near us.",
    "Come closer and the surface is a whole world of its own, made of fine warm texture.",
    "Step back out, and the ridge holds the whole evening in one quiet picture.",
]


def _build(P):
    sizes = _make_assets(P / "assets") if (P / "assets").mkdir(exist_ok=True) is None else None
    man = [{"id": k, "kind": "image", "file": f"assets/{k}.png", "route": "code", "width": w, "height": h,
            "provenance": {"tool": "test-procedural", "prompt": f"synthetic {k}"}} for k, (w, h) in sizes.items()]
    (P / "assets/manifest.json").write_text(json.dumps({"assets": man}))
    sc = json.loads((P / "scenes.json").read_text())
    tpl = sc["scenes"][0]
    voices = [("wonder", 2, "slower"), ("curious", 1, "steady"), ("calm", 1, "steady")]
    scenes = []
    for k in range(3):
        s = json.loads(json.dumps(tpl))
        s.update(id=f"s0{k + 1}", narration=NARR[k], visualIntensity=1, presentation="illustration", shortIds=["S01"])
        s.pop("signature", None)
        s["voice"].update(emotion=voices[k][0], intensity=voices[k][1], pace=voices[k][2], emphasisWords=["light"] if k == 0 else [])
        if k == 0:
            s["entities"] = [
                {"id": "bg", "role": "backdrop", "assetId": "plate", "enter": {"style": "none", "durationMs": 0}},
                {"id": "fg", "role": "subject", "assetId": "cutout", "enter": {"style": "rise", "durationMs": 2200}},
                {"id": "lab", "role": "label", "text": "Dusk", "enterAtWord": 3}]
            land = {"bg": {"x": 0.5, "y": 0.5, "w": 1.25, "z": 0, "depth": 1.0}, "fg": {"x": 0.3, "y": 0.66, "w": 0.34, "z": 2, "depth": 0.1}, "lab": {"x": 0.8, "y": 0.12, "w": 0.16, "z": 3}}
            port = {"bg": {"x": 0.2, "y": 0.5, "w": 3.0, "z": 0, "depth": 1.0}, "fg": {"x": 0.5, "y": 0.72, "w": 1.0, "z": 2, "depth": 0.1}, "lab": {"x": 0.5, "y": 0.12, "w": 0.3, "z": 3}}
            cam = [{"from": {"x": 0.5, "y": 0.5, "scale": 1.0}, "to": {"x": 0.62, "y": 0.5, "scale": 1.0}, "startWord": 0, "endWord": 12, "reason": "a slow lateral move so the near layer slides over the far one"}]
            s["transition"] = {"type": "nested_scale", "rationale": "the cut-out is the thing we move into: its surface becomes the detail plate",
                               "anchorFrom": {"entityId": "fg"}, "anchorTo": {"entityId": "det"}, "durationMs": 1400}
        elif k == 1:
            s["entities"] = [{"id": "det", "role": "subject", "assetId": "detail", "enter": {"style": "none", "durationMs": 0}}]
            land = {"det": {"x": 0.5, "y": 0.5, "w": 0.5, "z": 1}}
            port = {"det": {"x": 0.5, "y": 0.4, "w": 0.9, "z": 1}}
            cam = [{"from": {"x": 0.5, "y": 0.5, "scale": 1.0}, "to": {"x": 0.5, "y": 0.5, "scale": 1.05}, "startWord": 0, "endWord": 12, "reason": "a slow push into the texture"}]
            s["transition"] = {"type": "dissolve", "durationMs": 2000, "easing": "soft"}
        else:
            s["entities"] = [{"id": "bg3", "role": "backdrop", "assetId": "plate", "enter": {"style": "none", "durationMs": 0}}]
            land = {"bg3": {"x": 0.5, "y": 0.5, "w": 1.0, "z": 0}}
            port = {"bg3": {"x": 0.5, "y": 0.5, "w": 3.0, "z": 0}}
            cam = []
            s["transition"] = {"type": "cut"}
        s["layouts"] = {"landscape": {"placements": land, "camera": cam, **({"hold": {"reason": "let the quiet picture sit at the end"}} if k == 2 else {})},
                        "portrait": {"placements": port, **({"hold": {"reason": "the Short's own opening or closing line sits on a still picture"}} if k != 1 else {}), "camera": cam if k < 2 else [{"from": {"x": 0.5, "y": 0.5, "scale": 1.0}, "to": {"x": 0.5, "y": 0.5, "scale": 1.06}, "startWord": 0, "endWord": 12, "reason": "a slow settling push on the closing plate"}]}}
        scenes.append(s)
    sc["scenes"] = scenes
    (P / "scenes.json").write_text(json.dumps(sc, indent=1))
    sh = json.loads((P / "shorts.json").read_text())
    sh["shorts"][0]["sceneIds"] = ["s01", "s02", "s03"]
    (P / "shorts.json").write_text(json.dumps(sh, indent=1))


@pytest.fixture(scope="module")
def img():
    P = make_project("image-pipeline")
    _build(P)
    p = py("pipeline.py", "run", "--project", P, "--size", "640x360", "--targets", "long,S01", "--stack", "flite", "--auto-downgrade", timeout=1500)
    return P, p


def _frame(P, target, t, d):
    from PIL import Image
    r = run(["npx", "tsx", "engine/render.ts", "--project", P, "--target", target, "--dump-times", f"{t:.3f}", "--dump-dir", d, "--audio", "none"], timeout=600)
    assert r.returncode == 0, r.stdout[-800:] + r.stderr[-500:]
    return np.asarray(Image.open(sorted(pathlib.Path(d).glob(f"{target}-f*.png"))[-1]).convert("RGB"), dtype=float)


def _scene(P, target, sid):
    plan = json.loads((P / f"render/plan-{target}.json").read_text())
    return next(x for x in plan["scenes"] if x["id"] == sid)


def test_pipeline_delivers_both_files_and_both_gates_pass(img):
    P, p = img
    assert p.returncode == 0, p.stdout[-2500:] + p.stderr[-800:]
    for f, wh in (("out/full-video.mp4", (640, 360)), ("out/short-01.mp4", (360, 640))):
        v = ffprobe(P / f)["video"]
        assert (v["width"], v["height"]) == wh
        d = run(["ffmpeg", "-v", "error", "-nostdin", "-i", P / f, "-f", "null", "-"])
        assert d.returncode == 0 and d.stderr.strip() == ""
    for t in ("long", "S01"):
        assert json.loads((P / f"qa/motion-{t}.json").read_text())["overall"] == "PASSED"


def test_the_image_transition_is_the_planned_operator_and_not_a_silent_dissolve(img):
    P, _ = img
    for t in ("long", "S01"):
        tr = json.loads((P / f"render/trace-{t}.json").read_text())["transitions"]
        first = tr[0]
        assert first["planned"] == "nested_scale" and first["used"] == "nested_scale" and not first["fellBack"], first
        rep = json.loads((P / f"qa/motion-{t}.json").read_text())
        a = checks(rep, "motion.s01>s02.anchor")
        assert a and a[0]["status"] == "pass", "the anchor lands on the detail plate on every measured frame"


def test_transparent_layer_composites_over_the_plate(img, tmp_path):
    """The cut-out is opaque in its middle and fully transparent at the corner of its own box: the plate must show through there."""
    P, _ = img
    s = _scene(P, "long", "s01")
    f = _frame(P, "long", s["startS"] + 3.0, tmp_path / "l")
    H, W, _ = f.shape
    cx, cy, half = int(W * 0.30), int(H * 0.66), int(W * 0.34 / 2)
    centre = f[cy, cx]
    corner = f[cy - int(half * 0.95), cx - int(half * 0.95)]
    assert centre[1] > centre[0] + 25 and centre[1] > centre[2] + 10, f"cut-out centre should be green, got {centre}"
    assert not (corner[1] > corner[0] + 25 and corner[1] > corner[2] + 10), f"corner of the cut-out box must show the plate, got {corner}"


def test_parallax_far_layer_moves_less_than_near_layer(img, tmp_path):
    P, _ = img
    s = _scene(P, "long", "s01")
    a = _frame(P, "long", s["startS"] + 2.4, tmp_path / "a")
    b = _frame(P, "long", s["startS"] + 3.4, tmp_path / "b")

    def green_cx(f):
        m = (f[..., 1] > f[..., 0] + 25) & (f[..., 1] > f[..., 2] + 10)
        return np.nonzero(m)[1].mean()

    def sun_cx(f):
        m = (f[..., 0] > 235) & (f[..., 1] > 205)  # the plate's bright sun (rows above the caption band)
        m[int(f.shape[0] * 0.6):] = False
        assert m.sum() > 5, "sun visible"
        return np.nonzero(m)[1].mean()
    near, far = green_cx(b) - green_cx(a), sun_cx(b) - sun_cx(a)
    assert near * far > 0 and abs(near) > 0 and abs(far) > 0, (near, far)
    assert abs(near) > 1.4 * abs(far), f"near layer moved {near:.1f}px, far layer {far:.1f}px: no parallax"


def test_camera_push_moves_the_detail_plate(img, tmp_path):
    P, _ = img
    s = _scene(P, "long", "s02")
    a = _frame(P, "long", s["startS"] + 1.0, tmp_path / "a")
    b = _frame(P, "long", s["endS"] - 1.2, tmp_path / "b")
    assert np.abs(a - b).mean() > 0.5, "a camera push must change the picture"


def test_portrait_is_recomposed_not_squeezed(img, tmp_path):
    """The 16:9 plate in 9:16 is cropped around the sun side (x=0.2 of a 3-frame-wide plate), not scaled down: the sun is visible and the picture fills the frame."""
    P, _ = img
    s = _scene(P, "S01", "s03")
    f = _frame(P, "S01", (s["startS"] + s["endS"]) / 2, tmp_path / "p")
    H, W, _ = f.shape
    assert (H, W) == (640, 360)
    assert f.std() > 15, "the frame is filled with picture, not letterbox"
    assert f[:8].mean() > 25 and f[-8:].mean() > 25, "no black bars above/below"


def test_voice_direction_reaches_the_take_plan_and_continuity_is_recorded(img):
    P, _ = img
    plan = json.loads((P / "audio/take-plan.json").read_text())
    assert [t["emotion"] for t in plan["takes"]] == ["wonder", "curious", "calm"]
    assert [t["pace"] for t in plan["takes"]] == ["slower", "steady", "steady"]
    assert (P / "audio/voice-continuity.json").exists() and any((P / "audio").glob("master-*.wav"))


def test_loudness_of_the_delivered_file_is_in_range(img):
    P, _ = img
    rep = json.loads((P / "qa/test-placeholder.json").read_text()) if False else None
    p = run(["ffmpeg", "-nostdin", "-i", P / "out/full-video.mp4", "-af", "ebur128=peak=true", "-f", "null", "-"])
    import re
    m = re.findall(r"I:\s+(-?[\d.]+) LUFS", p.stderr)
    assert m and -20 < float(m[-1]) < -10, m


def test_regression_instant_entrance_plate_does_not_pop_in_a_dissolve_and_declared_fades_are_not_codec_noise(img):
    """v3.1 bugs found by this scenario: (1) an incoming plate with an instant entrance was hidden until the scene boundary and then appeared at the
    crossfade's current opacity (a 19-level one-frame pop in the middle of a dissolve); (2) the stillness calibration counted the declared closing fade
    as 'codec noise' in a long hold (a photographic plate held to the end -> freeze BLOCKED)."""
    P, _ = img
    m = json.loads((P / "qa/motion-long.json").read_text())
    assert [c["status"] for c in checks(m, "motion.s02>s03.pop")] == ["pass"] and [c["status"] for c in checks(m, "motion.s02>s03.exposure")] == ["pass"]
    q = json.loads((P / "qa/long.json").read_text())
    assert [c["status"] for c in checks(q, "freeze")] != ["blocked"] and q["overall"] == "PASSED", q["overall"]
